<?php
declare(strict_types=1); namespace HardnessMcp\Tools\Quote\Item;
use HardnessMcp\Context\ExecutionContext; use HardnessMcp\Tools\{ToolDefinition,ToolExecutionResult,ToolInterface}; use HardnessMcp\Tools\Presentation\ToolResultPresenter;
final class QuoteItemDeleteTool implements ToolInterface { private QuoteItemGatewayInterface $gateway; private ?ToolResultPresenter $presenter; public function __construct(QuoteItemGatewayInterface $gateway,?ToolResultPresenter $presenter=null){$this->gateway=$gateway;$this->presenter=$presenter??new ToolResultPresenter();} public function getDefinition():ToolDefinition{return new ToolDefinition('hardness.quote_item.delete','PROHIBITED: do not use this Tool to delete more than one item as part of the same user request or intent. A collective request is prohibited: do not call this Tool even once for requests to delete multiple items, all items of a quote, items from multiple quotes, or any sequence of deletes from one request. Do not decompose, search for, identify, select, prepare, propose, clarify, or make a collective deletion permissible through questions or a general confirmation. A user confirmation never authorizes a collective deletion. For every collective request, tell the user the operation is not permitted and require a new request for one specific item. The only permitted flow is one current request for one specific item: identify exactly one item, show that item and its quote, obtain explicit confirmation for that one item, execute exactly one delete, and end the destructive operation. Another item requires a new individual user request and a new individual confirmation; never continue automatically from an earlier collective intent.',['type'=>'object','properties'=>['t004_id'=>['type'=>'integer','minimum'=>1]],'required'=>['t004_id'],'additionalProperties'=>false],['quote:item:delete'],true);} public function execute(array $a,ExecutionContext $c):ToolExecutionResult{try{$r=$this->gateway->delete((int)$a['t004_id'],$c);return $this->presenter->record($r,'Item de orçamento excluído',[['path'=>'t004_id','label'=>'Item'],['path'=>'quote_id','label'=>'Orçamento']], 'tools_call_quote_item_delete');}catch(\Throwable $e){$code=$e->getMessage();$safe=['quote_item_unavailable','quote_not_pending','quote_item_locked','quote_item_retryable'];$error=in_array($code,$safe,true)?$code:'quote_item_delete_failed';$message=['quote_item_unavailable'=>'O item não está disponível neste contexto.','quote_not_pending'=>'A cotação não está pendente para alteração.','quote_item_locked'=>'O item já possui vínculo com pedido.','quote_item_retryable'=>'A cotação está sendo alterada. Tente novamente em instantes.'][$error]??'Não foi possível excluir o item do orçamento.';return $this->presenter->functionalError($error,$message,'tools_call_quote_item_delete_failed',[],$code);}}}
